"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[32042],{54879:e=>{e.exports=JSON.parse('{"functions":[{"name":"attach","desc":"Drives `model`\'s glow from its `Heat` / `Overheated` attributes until\\n`cleaner` cleans up.","params":[{"name":"model","desc":"","lua_type":"Model"},{"name":"cfg","desc":"","lua_type":"any"},{"name":"cleaner","desc":"","lua_type":"Janitor.Janitor"}],"returns":[],"function_type":"static","source":{"line":40,"path":"src/StarterPlayer/StarterPlayerScripts/TrainTurret/HeatGlow.luau"}}],"properties":[],"types":[],"name":"HeatGlow","desc":"Shows a heat-mode turret\'s heat on the model itself (Energy Cannon). The\\nneon parts named in `cfg.GlowParts` under the model\'s `Gun`, and every `Flow`\\nbeam under them, follow the replicated `Heat`: `cfg.HeatColors.cold` \u2192\\n`warm` over heat 0..0.6, `warm` \u2192 `hot` over 0.6..1. While `Overheated` they\\nblink `hot` / dim and the `Flow` beams stop (their TextureSpeed is restored on\\nunlock). Parts that stream in late are picked up through `ChildAdded`. All\\nwork happens on attribute changes; the blink loop only runs while overheated.","realm":["Client"],"source":{"line":14,"path":"src/StarterPlayer/StarterPlayerScripts/TrainTurret/HeatGlow.luau"}}')}}]);